CREATE OR REPLACE FUNCTION sp_getallproducts()
RETURNS TABLE(productid INTEGER, name VARCHAR(100), description VARCHAR(500), price NUMERIC(18,2), stockquantity INTEGER, createddate TIMESTAMP WITHOUT TIME ZONE, modifieddate TIMESTAMP WITHOUT TIME ZONE) AS $$
BEGIN
